      fidyahTitle: "What is Fidyah?",
      fidyahText1: "Fidyah is a compensation given by those who cannot fast due to valid reasons like chronic illness, old age, or other long-term disabilities.",
      fidyahText2: "In Ramadan, fasting is obligatory for all Muslims. Some people cannot fast due to legitimate reasons. For them, fidyah is a substitute method of fulfilling the fasts they missed.",
