      howFidyahTitle: "How is Fidya Paid?",
      howFidyahText: "Fidya is fulfilled by feeding the poor. The recompense is usually the equivalent of feeding a poor person two meals for each missed fast.",
      howFidyah1: "Often calculated based on staple foods like wheat or rice",
      howFidyah2: "If you miss all 30 fasts, you pay 30 days of fidya",
