      kaffarahText1: "Kaffarah is an expiation or punishment that becomes obligatory if someone commits a wilful infringement of a fast without a permissible cause.",
      kaffarahText2: "If a person intentionally breaks a fast in Ramadan without valid reason, they must fast for 60 days consecutively or feed 60 poor persons if unable to fast.",
