      hadithTitle: "Hadith Confirming Hajj/Umrah Badal",
      hadith1: "Abdullah ibn Abbas narrated: A woman asked about her old father who could not perform Hajj/Umrah. The Prophet ﷺ replied: “Yes, you may perform Hajj and Umrah on his behalf... Fulfill the obligations of your parents.” (Abu Dawood)",
