      faqTitle: "Frequently Asked Questions",
      faq1Q: "What is Hajj e Badal Service?",
      faq1A: "Hajj e Badal is the performance of Hajj on behalf of someone unable due to long illness, old age, or death.",
      faq2Q: "Hajj e badal ka tarika (Procedure of Hajj e Badal)",
      faq2A: "The proxy must have performed obligatory Hajj, intend on behalf of the person, mention them in Talbiyah, then perform all rituals as regular Hajj.",
      faq3Q: "Badal Hajj for a Deceased Person",
      faq3A: "Yes, it is allowed for someone obligated to do Hajj but died without performing it (Sahih Bukhari 1852, Sahih Muslim 1148).",
      faq4Q: "Can we do Umrah Badal?",
      faq4A: "Yes, Umrah Badal is permissible if the person is permanently unable or has passed away without performing it.",
      faq5Q: "For whom may Hajj e Badal be performed?",
      faq5A: "For those who had the means but couldn't due to old age, prolonged illness, disability, or death (not temporary illness).",
