      introP2: "All the actions of Umrah follow the example of Prophet Ibrahim (AS) and Prophet Muhammad (PBUH).",
      prepEyebrow: "Preparation",
      prepTitle: "Preparation for Umrah",
      prep1Title: "Sincere Intention (Niyyah)",
      prep1Desc: "Perform Umrah for Allah's sake alone.",
      prep2Title: "Understanding Rituals",
      prep2Desc: "Learn each step to get it right.",
      prep3Title: "Ghusl (Purification)",
      prep3Desc: "Clean the entire body before donning Ihram.",
      prep4Title: "Financial Preparedness",
      prep4Desc: "Make all the expenses halal.",
      prep5Title: "Personal Matters",
      prep5Desc: "Ask others for forgiveness and clear outstanding debts.",
      stepsEyebrow: "Steps",
      stepsTitle: "Step-by-Step Umrah Guide",
      step1Title: "Ihram & Niyyah (Entering the State of Ihram)",
      step1Desc: "Ihram is the sacred state required for the performance of Umrah. Men wear two white unstitched garments (Izar & Rida). Women dress in proper attire covering the whole body (except hands and face).",
      step1Dua1Arabic: "اللَّهُمَّ إِنِّي أُرِيدُ العُمْرَةَ فَيَسِّرْهَا لِي وَتَقَبَّلْهَا مِنِّي",
      step1Dua1Translation: "“Ya Allah, I am planning to do the Umrah, make it easy for me and accept it from me.”",
      step1TalbiyahLabel: "Recite Talbiyah:",
      step1Dua2Arabic: "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الحَمْدَ وَالنِّعْمَةَ لَكَ وَالمُلْكَ، لاَ شَرِيكَ لَكَ",
      step1Dua2Translation: "“Here I am, O Allah. There is no partner with You. Indeed, all the blessings and the grace and the kingdom are Yours.”",
      step2Title: "Entering the Al-Haram",
      step2Desc: "Step with the right foot and say the dua. Walk towards the Ka'bah with a humble and respectful demeanour.",
      step2DuaArabic: "للهم افتح لي ابواب رحمت",
      step2DuaTranslation: "“Oh Allah, open the doors of mercy for me.”",
      step3Title: "Tawaf (Circumambulation of the Ka'bah)",
      step3Desc: "Tawaf consists of seven circuits around the Ka'bah anticlockwise. Start with the Black Stone (Hajar al-Aswad). If possible, kiss or touch it. If not, point toward it with your right hand.",
      step3DuaArabic: "بسم الله، والله أكبر",
      step3DuaTranslation: "“In the name of Allah. Allah is the greatest.”",
      step4Title: "Sa'i (Between Safa and Marwah)",
      step4Desc: "At the beginning of Safa, recite the verse from Surah Al-Baqarah. Walk seven rounds from Marwah to Safa. Men must cross between green lights, and women must cross normally.",
      step4DuaArabic: "إِنَّ الصَّفَا وَالمَرْوَةَ مِن شَعَائِرِ اللَّهِ",
      step4DuaTranslation: "“Indeed, Safa and Marwah are among the signs of Allah.” (Surah Al-Baqarah 2:158)",
      step5Title: "Halq/Taqsir (Shaving or Trimming Hair)",
      step5Desc: "For men: Shave the head completely (Halq) or trim hair from all areas equally (Taqsir). For women: Clip a tip-of-the-fingertip amount of hair (only Taqsir is allowed).",
      step5Conclusion: "Once this step is complete, Umrah is finished. You are now allowed to leave Ihram.",
      duasEyebrow: "Duas",
      duasTitle: "Obligatory Duas for Umrah",
      dua1Title: "Dua for Flying by Airplane",
      dua1Arabic: "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ",
      dua1Translation: "“Glory be to Him who subjected this unto us; we were incapable.”",
      dua2Title: "Dua for Tawaf",
      dua2Arabic: "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",
      dua2Translation: "“Our Lord, grant us good in the world and the Hereafter and save us from the torment of the Fire.”",
      rulesEyebrow: "Special Rules",
      rulesTitle: "Special Rules for Women",
      rule1: "Women cannot wear perfume or makeup in Ihram.",
      rule2: "Prayers during menses: Women are required to delay their Tawaf after their purification.",
      rule3: "Modest attire must be worn, but face masks are not allowed while wearing Ihram.",
