      ctaText: "Performing the Umrah is a spiritually enriching experience which deepens faith and piety. May Allah accept your Umrah and bless you. Ameen!",
      ctaWhatsAppBtn: "Book via WhatsApp Now",
      ctaCallBtn: "Call Us Direct",
