      fleet2Desc: "مثالية للعائلات مع الأطفال أو المجموعات تسافر معًا. المساحة الإضافية تجعل الرحلات الطويلة أكثر راحة.",
      fleet3Title: "حافلة كوستر",
      fleet3Pax: "12-14 ركاب",
      fleet3Bag: "سعة أمتعة المجموعة",
      fleet3Desc: "تعمل هذه بشكل مثالي لمجموعات الأسرة الموسعة أو الأصدقاء يسافرون معًا للعمرة. يبقى الجميع معًا.",
      fleetBookBtn: "احجز الآن عبر واتساب",
      ctaEyebrow: "الخاتمة",
