      madinahText2: "Kami menangani pemesanan taksi hotel Madinah untuk kunjungan ke Masjid Nabawi, Masjid Quba, dan Gunung Uhud. Sopir kami menyarankan waktu kunjungan terbaik untuk menghindari kerumunan. Mereka menunggu dengan sabar saat Anda menyelesaikan Ziyarat Anda.",
      madinahText3: "Kunjungan malam ke pasar kurma atau pasar tradisional? Kami membawa Anda berbelanja dan mengembalikan Anda dengan aman. Sopir kami merekomendasikan toko otentik di mana penduduk lokal berbelanja. Anda menghindari jebakan turis yang mengenakan harga yang melambung.",
      jeddahTitle: "Layanan Taksi Transportasi Hotel Jeddah",
      jeddahText1: "Layanan taksi transportasi hotel Jeddah melayani jamaah dan pelancong bisnis. Jeddah berfungsi sebagai kota gerbang bagi sebagian besar pengunjung Umrah. Banyak orang menghabiskan malam di sini sebelum bepergian ke Makkah atau setelah menyelesaikan Umrah sebelum terbang pulang.",
      jeddahText2: "Kami memindahkan Anda antara hotel dan atraksi wisata. Jika Anda ingin melihat distrik Al-Balad bersejarah atau berjalan di sepanjang Corniche, kami akan membawa Anda dengan nyaman.",
      jeddahText3: "Hotel-hotel Jeddah berkisar dari anggaran hingga kemewahan bintang lima. Layanan kami mencakup semua kategori harga. Kami tidak menghakimi berdasarkan tempat Anda menginap. Setiap penumpang menerima rasa hormat dan layanan luar biasa yang sama terlepas dari status hotel.",
