      jeddahAirportText2: "Sopir Anda bertemu Anda di kedatangan Bandara Jeddah. Dia melacak penerbangan Anda, jadi Anda tidak perlu menelepon untuk menjelaskan keterlambatan. Dia membawa tanda dengan nama Anda tercetak dengan jelas. Anda menemukannya dengan mudah di antara kerumunan. Dalam hitungan menit, Anda duduk di kendaraan bersih menuju Makkah.",
      jeddahAirportText3: "Kami berhenti di Miqat jika Anda perlu memasuki Ihram. Sopir Anda menunjukkan fasilitas dan menunggu dengan sabar. Dia memastikan Anda menyelesaikan ritual penting ini dengan benar. Untuk keluarga dengan anak kecil, kami mengizinkan istirahat ke kamar mandi tanpa biaya tambahan.",
      madinahAirportTitle: "Bandara Madinah ke Hotel Madinah",
      madinahAirportText1: "Taksi bandara Madinah ke hotel Madinah membawa Anda langsung dari Bandara Internasional Pangeran Mohammad bin Abdulaziz ke akomodasi Anda. Bandara terletak di luar kota, membutuhkan transportasi andal. Anda tidak bisa berjalan ke hotel dari sana.",
      madinahAirportText2: "Bandara Madinah lebih kecil dari Bandara Jeddah. Sopir kami menavigasinya dengan mudah. Mereka menunggu di keluar yang benar, memastikan pertemuan cepat. Perjalanan ke hotel pusat kota memakan waktu 15-25 menit, tergantung lokasi.",
      madinahAirportText3: "Kami mengemudi melewati perkebunan kurma yang indah dan pembangunan modern. Sopir kami menunjukkan landmark, membantu Anda mengorientasikan diri di kota. Pengantar ramah ini membuat pengunjung pertama kali merasa diterima dan nyaman.",
      whyTitle: "Mengapa Haramain Menawarkan Transfer Hotel Terbaik?",
      whySubtitle: "Transfer hotel terbaik menggabungkan keandalan, kenyamanan, dan harga yang adil. Kami telah menyempurnakan keseimbangan ini selama bertahun-tahun melayani jamaah dan turis.",
      whyFeature1Title: "Kendaraan Sempurna",
