          id: 'q6',
          question: 'Bagaimana cara menempah dan kaedah pembayaran apa yang anda terima?',
          answer: 'Tempahan mudah – hubungi kami melalui WhatsApp atau tekan butang "Tempah Sekarang" di laman web kami. Kami akan memberi anda sebut harga berdasarkan laluan dan pilihan kenderaan anda. Setelah anda berpuas hati, kami akan mengamankan tempahan anda. Kami menerima pelbagai kaedah pembayaran dan akan membincangkan pilihan apabila anda menempah. Keseluruhan proses biasanya hanya mengambil masa beberapa minit.'
